import * as filesystem from 'node:fs/promises';
import { mock } from 'bun:test';

const nativeReaddir = filesystem.readdir;
mock.module('node:fs/promises', () => ({
  ...filesystem,
  readdir: async (...arguments_) => {
    const entries = await nativeReaddir(...arguments_);
    return entries.sort((left, right) =>
      String(typeof right === 'object' && 'name' in right ? right.name : right).localeCompare(
        String(typeof left === 'object' && 'name' in left ? left.name : left),
      ),
    );
  },
}));
